{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_6",
      "quote": "Systematic reviews of randomised controlled trials provide the strongest evidence to underpin healthcare decisions... Nevertheless, Cochrane Reviews have been greatly under-utilised in guidelines and recommendations are often based on lowerlevel evidence or expert consensus because of limitations regarding familiarity, awareness, usefulness, access, and time [12-21]. Limited research has explored the use of NMAs to inform guidelines [38].",
      "reason": "The introduction describes the current state of knowledge (systematic reviews as strongest evidence, Cochrane reviews as high quality but under-utilized) and important uncertainties (limitations regarding familiarity, limited research on NMA use in guidelines)."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_6",
      "quote": "Review authors strive to maximise the impact of their review in terms of improvements to patient heath... Yet, if a review does not provide evidence to strengthen or change recommendations... the review could potentially have very limited impact... Our article is the first to systematically search for reviews and summarise their citation in guidelines... Weanticipate that our research will highlight the extent of potential research waste, help review authors to maximise the impact of their reviews...",
      "reason": "The text explains the importance of maximizing review impact and the need for the current review to identify research waste and help review authors and guideline developers improve efficiency."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "PRESENT",
      "chunk_id": "text_6",
      "quote": "Previous work has reviewed guidelines and summarised the type of evidence that underpinned recommendations [12, 13, 15]. Limited research has explored the use of NMAs to inform guidelines [38]. Lunny et al summarised how often NMAs and PW-MAs support recommendations in a sample of 50 guidelines [15]. Our article is the first to systematically search for reviews and summarise their citation in guidelines... However, to our knowledge, no research has reviewed PW-MA reviews and summarised their citation in guidelines or compared samples of NMA reviews and PW-MAreviews in terms of citation.",
      "reason": "The manuscript identifies existing reviews (Lunny et al, others) and explains the need for the current review by highlighting the gap in comparing citation of NMA vs PW-MA reviews specifically."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "This is a systematic review of systematic reviews regarding citation in guidelines, not a review of intervention effects on health outcomes. Therefore, describing a mechanism of action for an intervention is not applicable."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "This is a systematic review of systematic reviews regarding citation in guidelines, not a review of complex interventions or delivery contexts. Therefore, considering a logic model is not applicable."
    }
  ],
  "confidence": 95
}

